/* Guided onboarding: preferences are explicit, never inferred from faces. */
(function(root){
 const personas=[['minimal','Clean & minimal','Quiet colours, simple shapes, easy repeats.'],['street','Streetwear','Relaxed silhouettes, denim and statement layers.'],['tailored','Modern tailoring','Structured pieces and polished combinations.'],['expressive','Colour & expression','Prints, colour and playful accessories.'],['relaxed','Relaxed everyday','Comfortable fits and versatile casual pieces.'],['exploring','Still exploring','Try different directions without a fixed label.']];
 const steps=[{key:'current',question:'What feels closest to your style right now?',options:personas.map(p=>[p[0],p[1]])},{key:'occasion',question:'What are we dressing for most often?',options:[['everyday','Everyday plans'],['work','Work / college'],['evening','Going out'],['travel','Trips & weekends']]},{key:'priority',question:'What matters most when you choose a fit?',options:[['comfort','Comfort first'],['versatility','More ways to wear it'],['statement','Making a statement'],['polish','Feeling put together']]},{key:'target',question:'Your Target Persona: what do you want to explore next?',options:personas.map(p=>[p[0],p[1]])}];
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function clean(value){const p={};for(const s of steps)if(s.options.some(o=>o[0]===value?.[s.key]))p[s.key]=value[s.key];if(typeof value?.note==='string')p.note=value.note.slice(0,240);return p;}
 function summary(p){p=clean(p);return {complete:steps.every(s=>p[s.key]),current:personas.find(x=>x[0]===p.current)?.[1]||'Still exploring',target:personas.find(x=>x[0]===p.target)?.[1]||'Not chosen yet'};}
 if(typeof module!=='undefined')module.exports={steps,personas,clean,summary};
 if(!root?.document)return;
 let p={};try{p=clean(JSON.parse(localStorage.getItem('tbw-persona-v1')))}catch{}
 let photos=[],step=steps.findIndex(s=>!p[s.key]),editing=false,message='',config=null,token='',session=null,busy=false,nextCheck=0;
 const save=()=>{try{localStorage.setItem('tbw-persona-v1',JSON.stringify(p));message='Saved on this browser.';}catch{message='Browser storage is unavailable. Your answers last for this session.';}};
 const repaint=()=>{root.dispatchEvent(new Event('persona-change'));};
 function photoPanel(){return `<section class="persona-sources"><h2>Your style references <span class="note">Optional</span></h2><p>Choose photos of your outfits or looks you want to try. Photos stay in this tab; they are not analysed by AI or added as owned clothes.</p><div class="chip-row"><label class="btn secondary">Choose device photos<input id="persona-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></label><button class="btn secondary" data-persona="google" ${busy||session?'disabled':''}>${busy?'Connecting…':'Choose from Google Photos'}</button></div>${session?`<a class="btn secondary" href="${escape(session.pickerUri)}" target="_blank" rel="noopener noreferrer">Open photo picker</a><button class="btn" data-persona="collect" ${busy?'disabled':''}>I’ve selected my photos</button><button class="link-btn" data-persona="cancel">Cancel import</button>`:''}<details><summary>Instagram photos</summary><p>Direct personal-account import is unavailable. Save the photos you want from your own account, then choose them above. Professional-account support is planned, not connected.</p></details><div class="persona-photos">${photos.map((x,i)=>`<figure><img src="${escape(x.url)}" alt="Style reference ${i+1}"><button class="link-btn" data-persona="remove" data-index="${i}" aria-label="Remove reference ${i+1}">Remove</button></figure>`).join('')}</div>${photos.length?'<button class="link-btn" data-persona="clear-photos">Clear all references</button>':''}</section>`;}
 function render(profile=false){const s=summary(p),index=step<0?steps.length:step;return `<div class="persona-shell"><div class="persona-heading"><span class="pill">${profile?'My Profile':'Style Me · your starting point'}</span><h1>${profile?'Your style, your call.':'Search what kind of persona you are.'}</h1><p>A few choices to find your direction. You can change your mind anytime.</p></div><section class="persona-chat" aria-label="Style persona chat"><div class="persona-progress" role="progressbar" aria-label="Answered style questions" aria-valuemin="0" aria-valuemax="4" aria-valuenow="${steps.filter(x=>p[x.key]).length}"><span style="width:${steps.filter(x=>p[x.key]).length*25}%"></span></div><p class="note">Guided chat · ${steps.filter(x=>p[x.key]).length} of 4 answered</p>${(!s.complete||editing)?`${steps.slice(0,index).map(q=>`<div class="persona-bubble">${escape(q.question)}</div><div class="persona-answer">${escape(q.options.find(o=>o[0]===p[q.key])?.[1])}</div>`).join('')}<div class="persona-bubble" role="status">${escape(steps[index]?.question||'Your direction is ready.')}</div><div class="persona-options">${(steps[index]?.options||[]).map(([v,l])=>`<button class="persona-option" data-persona="answer" data-value="${v}">${escape(l)}</button>`).join('')}</div>${index>0?'<button class="link-btn" data-persona="back">Back one question</button>':''}`:`<span class="pill">Style direction unlocked</span><h2>${escape(s.current)}</h2><p>${escape(personas.find(x=>x[0]===p.current)?.[2])}</p><div class="persona-target"><span class="note">TARGET PERSONA</span><h3>${escape(s.target)}</h3><p>${escape(steps[1].options.find(x=>x[0]===p.occasion)?.[1])} · ${escape(steps[2].options.find(x=>x[0]===p.priority)?.[1])}</p></div><button class="link-btn" data-persona="edit">Edit my answers</button>`}<label class="persona-note">Anything else about your style? <span class="note">Optional</span><textarea id="persona-note" maxlength="240" placeholder="I like oversized shirts, but no loud logos…">${escape(p.note||'')}</textarea></label><p class="note">Your note is saved as a preference, not interpreted by a chatbot yet.</p></section>${photoPanel()}<p class="persona-status" role="status">${escape(message)}</p><div class="persona-next"><a class="btn" href="#style/outfits">Explore the outfit board →</a><a class="btn secondary" href="#wardrobe">Open My Wardrobe</a><a class="link-btn" href="#discover">Find an inspiration piece</a></div><p class="note">The outfit board still uses preset demo looks; persona-based recommendations are the next step.</p>${profile?'<section class="panel"><h2>Insights</h2><p>Coming soon</p></section><button class="link-btn" data-persona="reset">Delete my persona and references</button>':''}</div>`;}
 async function api(action,body={}){const r=await fetch('/api/photos/'+action,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(body),signal:AbortSignal.timeout(110000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Photo import failed.');return data;}
 async function cancel(){const old=session;session=null;if(old&&token)try{await api('delete',{sessionId:old.id});}catch{}token='';busy=false;}
 async function google(){if(busy||session)return;if(!config?.googleClientId){message='Google Photos needs a Google OAuth client ID configured by the developer. Device photos work now.';return;}
 message='Google shares only the photos you choose. We use them as temporary style references, not for ads or model training.';busy=true;repaint();
 try{if(!root.google?.accounts?.oauth2){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=resolve;script.onerror=()=>reject(Error('Google sign-in could not load. Try device photos.'));document.head.append(script);});}
 root.google.accounts.oauth2.initTokenClient({client_id:config.googleClientId,scope:'https://www.googleapis.com/auth/photospicker.mediaitems.readonly',callback:async result=>{try{if(result.error||!result.access_token)throw Error('Google Photos permission was not granted.');token=result.access_token;session=await api('create');nextCheck=Date.now()+Math.max(1000,parseFloat(session.pollingConfig?.pollInterval||'5')*1000);message='Open the picker, choose up to six outfit photos, then return here.';}catch(e){message=e.message;await cancel();}finally{busy=false;repaint();}},error_callback:()=>{busy=false;message='Sign-in closed or blocked. Try again, or choose device photos.';repaint();}}).requestAccessToken();
 }catch(e){busy=false;message=e.message;}}
 async function collect(){if(!session||busy)return;if(Date.now()<nextCheck){message='Give the picker a moment, then try again.';return;}busy=true;repaint();try{const result=await api('collect',{sessionId:session.id});if(!result.ready){nextCheck=Date.now()+Math.max(1000,parseFloat(result.pollingConfig?.pollInterval||'5')*1000);message='Selection is not finished. Complete it in Google Photos first.';return;}for(const image of result.images){if(photos.length===6)break;photos.push({url:image.dataUrl});}message=result.images.length?'Selected photos added. Review or remove them below.':'No supported photos selected. Choose JPEG, PNG or WebP images.';await cancel();}catch(e){message=e.message;await cancel();}finally{busy=false;}}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-persona]');if(!b||b.disabled)return;const a=b.dataset.persona;if(a==='answer'){const q=steps[step<0?0:step];if(!q.options.some(x=>x[0]===b.dataset.value))return;p[q.key]=b.dataset.value;step++;if(step>=steps.length){step=-1;editing=false;}save();}if(a==='back'){step=Math.max(0,step-1);editing=true;}if(a==='edit'){step=0;editing=true;}if(a==='reset'){p={};step=0;editing=false;photos.forEach(x=>{if(x.url.startsWith('blob:'))URL.revokeObjectURL(x.url)});photos=[];await cancel();save();message='Persona and references deleted.';}if(a==='clear-photos'){photos.forEach(x=>{if(x.url.startsWith('blob:'))URL.revokeObjectURL(x.url)});photos=[];}if(a==='remove'){const [x]=photos.splice(Number(b.dataset.index),1);if(x?.url.startsWith('blob:'))URL.revokeObjectURL(x.url);}if(a==='google')await google();if(a==='collect')await collect();if(a==='cancel'){await cancel();message='Import cancelled.';}repaint();});
 document.addEventListener('change',e=>{if(e.target.id==='persona-note'){p.note=e.target.value.slice(0,240);save();repaint();}if(e.target.id==='persona-files'){let rejected=0;for(const f of e.target.files){if(photos.length>=6||!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){rejected++;continue;}photos.push({url:URL.createObjectURL(f)});}message=rejected?'Some files were skipped. Choose up to six JPEG, PNG or WebP photos, each under 10 MB.':'Photos added for this tab only.';repaint();}});
 fetch('/api/photos/config').then(r=>r.json()).then(x=>config=x).catch(()=>{});
 root.Persona={render,summary:()=>summary(p)};
})(typeof window==='undefined'?null:window);
